        .expect("mock app");

    let identity_a = WorktreeIdentity {
        ws_id: "agent".into(),
        slug: "slot-a".into(),
    };
    let identity_b = WorktreeIdentity {
        ws_id: "agent".into(),
        slug: "slot-b".into(),
    };
    let created_a = cmd_worktree_create(
        app.handle().clone(),
        app.state::<WorkspaceRegistry>(),
        CreateWorktreeRequest {
            workspace_id: "workspace-a".into(),
            worktree: identity_a.clone(),
