+    // Spawn Shell A and Shell B
+    let session_a = client_a
+        .spawn("req-persist-a", ws_id, 80, 24)
+        .await
+        .expect("Spawn Shell A failed");
+    let session_b = client_a
+        .spawn("req-persist-b", ws_id, 80, 24)
+        .await
+        .expect("Spawn Shell B failed");
+
